 */
public static String region(String memberId) {
    if (memberId == null) {
        return UNKNOWN_REGION;
    }
    int i = 0;
    while (i < memberId.length() && !Character.isDigit(memberId.charAt(i))) {
        i++;
    }
    return i == 0 ? UNKNOWN_REGION : memberId.substring(0, i);
}

